# Glue Data Catalog table definition -- Terraform
resource "aws_glue_catalog_database" "pipeline" {
  name = "orders_pipeline"
}

resource "aws_glue_catalog_table" "orders_processed" {
  name          = "orders_processed"
  database_name = aws_glue_catalog_database.pipeline.name
  table_type    = "EXTERNAL_TABLE"

  storage_descriptor {
    location      = "s3://bucket/processed/orders/"
    input_format  = "org.apache.hadoop.hive.ql.io.parquet.MapredParquetInputFormat"
    output_format = "org.apache.hadoop.hive.ql.io.parquet.MapredParquetOutputFormat"
    ser_de_info { serialization_library = "org.apache.hadoop.hive.ql.io.parquet.serde.ParquetHiveSerDe" }
    columns { name = "customer_id"; type = "int" }
    columns { name = "amount"; type = "double" }
  }

  partition_keys { name = "order_date"; type = "string" }
}

-- Athena query -- partition pruning keeps the scan (and cost) small
SELECT category, SUM(amount) AS total
FROM orders_pipeline.orders_processed
WHERE order_date = '2024-01-15'
GROUP BY category;

-- CTAS -- materialize a pre-aggregated table for repeated dashboard queries
CREATE TABLE orders_pipeline.daily_category_summary
WITH (format = 'PARQUET', external_location = 's3://bucket/agg/daily_category/')
AS
SELECT order_date, category, SUM(amount) AS total, COUNT(*) AS order_count
FROM orders_pipeline.orders_processed
GROUP BY order_date, category;

# Glue Crawler -- auto-discover schema for a new source (use selectively)
resource "aws_glue_crawler" "new_source" {
  name          = "new-source-crawler"
  database_name = aws_glue_catalog_database.pipeline.name
  role          = aws_iam_role.glue_crawler.arn
  s3_target { path = "s3://bucket/raw/new-source/" }
  schedule = "cron(0 7 * * ? *)"
}
